.vpip-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  cursor: pointer;
}
.vpip-wrapper.active {
  filter: drop-shadow(0 0 12px rgba(59,130,246,0.4));
}
.vpip-svg {
  width: 36px;
  height: 230px;
  transition: transform 0.2s, filter 0.2s;
  filter: drop-shadow(0 2px 5px rgba(0,0,0,0.06));
}
.vpip-svg.hovered {
  transform: scale(1.08);
  filter: drop-shadow(0 4px 10px rgba(0,0,0,0.1));
}
.drop-canvas {
  position: absolute;
  top: 0;
  left: 50%;
  width: 40px;
  height: 280px;
  margin-left: -20px;
  z-index: 2;
  pointer-events: none;
}

